6	export type Item = {
7	  type: string;
8	  material?: string;
9	  enchantment?: number;
10	  cursed?: boolean;
11	};
12	
13	const PROCESSING_FEE = 5;
14	
15	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
16	  sword: 100,
17	  amulet: 60,
18	  staff: 80,
19	  potion: 40,
20	  rune: 25,
21	  moonstone: 25,
22	};
23	
24	const basePremiumOf = (item: Item): number =>
25	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
26	
27	const sumBasePremiums = (items: Item[]): number =>
28	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
29	
30	const BLOCK_SIZE = 3;
31	const BLOCK_BASE_PREMIUM = 60;
32	
33	const formsComponentBlock = (items: Item[]): boolean =>
34	  items.length === BLOCK_SIZE;
35	
36	const groupByType = (items: Item[]): Item[][] => {
37	  const groups = new Map<string, Item[]>();
38	  for (const item of items) {
39	    const group = groups.get(item.type) ?? [];
40	    group.push(item);
41	    groups.set(item.type, group);
42	  }
43	  return [...groups.values()];
44	};
45	
46	const basePremiumOfGroup = (group: Item[]): number =>
47	  formsComponentBlock(group) ? BLOCK_BASE_PREMIUM : sumBasePremiums(group);
48	
49	export const quote = (customer: Customer, items: Item[]): number => {
50	  const policyBasePremium = groupByType(items).reduce(
51	    (sum, group) => sum + basePremiumOfGroup(group),
52	    0,
53	  );
54	
55	  return policyBasePremium + PROCESSING_FEE;
56	};
57	
58	export const claim = (): number => {
59	  return undefined as unknown as number;
60	};
